import numpy as np
from scipy.optimize import least_squares
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
def m(p,kind):
    f=p[0]*np.exp(-p[1]*t**2)+p[2]*v+p[3]*np.exp(-p[4]*x)*np.abs(v)**p[5]
    if kind=='sin': f=f+p[6]*np.sin(p[7]*t+p[8])
    if kind=='poly': f=f+p[6]*t+p[7]*t**2+p[8]*t**3
    if kind=='tanh': f=f+p[6]*np.tanh(p[7]*(t-p[8]))
    return f
def R2(f): return 1-np.sum((y-f)**2)/np.sum((y-y.mean())**2)
np.random.seed(2)
for kind,extra in [('poly',3),('tanh',3),('sin',3)]:
    best=None
    for s in range(40):
        p0=np.r_[np.random.randn(1)*5, 0.02, np.random.randn(1)*3, 3.4, 1.0, 0.5, np.random.randn(1), np.random.uniform(0.1,2,1)[0], np.random.uniform(0,6,1)[0]]
        if kind=='poly': p0[6:9]=np.random.randn(3)*0.3
        try:
            r=least_squares(lambda p: m(p,kind)-y, p0)
        except Exception: continue
        if best is None or r.cost<best.cost: best=r
    print(kind, best.x.round(4), R2(m(best.x,kind)), np.mean(best.fun**2)/np.var(y))

